package com.smartproperty.platform.billing.vo;
import java.math.BigDecimal;
import java.time.LocalDate;
/** Bean-style VO avoids driver-specific constructor conversion for financial view columns. */
public class BillListVO {
    private Long billId; private String billNo; private String propertyNo; private String communityName; private String fullLocation; private Integer billingYear; private Integer billingMonth; private BigDecimal receivableAmount; private BigDecimal receivedAmount; private BigDecimal outstandingAmount; private LocalDate dueDate; private String status;
    public Long getBillId(){return billId;} public void setBillId(Long v){billId=v;} public String getBillNo(){return billNo;} public void setBillNo(String v){billNo=v;} public String getPropertyNo(){return propertyNo;} public void setPropertyNo(String v){propertyNo=v;} public String getCommunityName(){return communityName;} public void setCommunityName(String v){communityName=v;} public String getFullLocation(){return fullLocation;} public void setFullLocation(String v){fullLocation=v;} public Integer getBillingYear(){return billingYear;} public void setBillingYear(Integer v){billingYear=v;} public Integer getBillingMonth(){return billingMonth;} public void setBillingMonth(Integer v){billingMonth=v;} public BigDecimal getReceivableAmount(){return receivableAmount;} public void setReceivableAmount(BigDecimal v){receivableAmount=v;} public BigDecimal getReceivedAmount(){return receivedAmount;} public void setReceivedAmount(BigDecimal v){receivedAmount=v;} public BigDecimal getOutstandingAmount(){return outstandingAmount;} public void setOutstandingAmount(BigDecimal v){outstandingAmount=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;}
}
